// ─────────────────────────────────────────────────────────────────────────
//  01 · read and translate safely★★☆
//  concepts: try-with-resources · causes · UncheckedIOException
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.io.*;
import java.util.*;
import java.util.function.*;

class Exercise {

    /** Sum of one cents amount per line; translated failures; reader always closed. */
    static long sumAmounts(Supplier<BufferedReader> open) {
        try (BufferedReader r = open.get()) {
            long total = 0;
            int lineNo = 0;
            for (String line = r.readLine(); line != null; line = r.readLine()) {
                lineNo++;
                if (line.isBlank()) continue;
                try {
                    total += Long.parseLong(line.strip());
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("line " + lineNo + ": not an amount", e);
                }
            }
            return total;
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static final class Tracking extends BufferedReader {
        boolean closed;
        final int failAfter;
        int reads;
        Tracking(String text, int failAfter) { super(new StringReader(text)); this.failAfter = failAfter; }
        @Override public String readLine() throws IOException {
            if (reads++ >= failAfter) throw new IOException("disk read failed");
            return super.readLine();
        }
        @Override public void close() throws IOException { closed = true; super.close(); }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("sums lines and closes the reader", () -> {
            var r = new Tracking("100\n\n 250 \n", Integer.MAX_VALUE);
            eq(sumAmounts(() -> r), 350L);
            ok(r.closed, "reader not closed");
        });
        test("a bad line names its number and keeps the cause", () -> {
            var r = new Tracking("100\nabc\n", Integer.MAX_VALUE);
            var e = raises(IllegalArgumentException.class, () -> sumAmounts(() -> r));
            ok(e.getMessage().contains("line 2") && e.getCause() instanceof NumberFormatException, "message and cause");
            ok(r.closed, "reader not closed after a bad line");
        });
        test("an IO failure is wrapped with its cause", () -> {
            var r = new Tracking("1\n2\n", 1);
            var e = raises(UncheckedIOException.class, () -> sumAmounts(() -> r));
            ok(e.getCause() != null && e.getCause().getMessage().equals("disk read failed"), "cause kept");
            ok(r.closed, "reader not closed after an IO failure");
        });
        test("an empty file sums to zero (boundary)", () -> eq(sumAmounts(() -> new Tracking("", Integer.MAX_VALUE)), 0L));
        test("negative amounts are allowed", () -> eq(sumAmounts(() -> new Tracking("-50\n20\n", Integer.MAX_VALUE)), -30L));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Declare the reader in the try header and translate inside it:

```java
try (BufferedReader r = open.get()) {
    long total = 0;
    int lineNo = 0;
    for (String line = r.readLine(); line != null; line = r.readLine()) {
        lineNo++;
        if (line.isBlank()) continue;
        try {
            total += Long.parseLong(line.strip());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("line " + lineNo + ": not an amount", e);
        }
    }
    return total;
} catch (IOException e) {
    throw new UncheckedIOException(e);
}
```

The reader closes before the outer catch runs, on success and on both failure paths. Passing `e` as the cause keeps the original exception for the logs.
